use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioDrawingSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let a=SemioPoint2{x:1.0,y:2.0};let b=SemioPoint2{x:3.0,y:4.0};SemioDrawingSnapshot{schema:f["schema"].as_str().unwrap().into(),canvas:DrawCanvas{width:1920.5,height:1080.25,background:Some(SemioRgba{r:0.25,g:0.5,b:0.75,a:1.0})},styles:vec![DrawStyle{name:"".into(),fill:Some(SemioRgba{r:0.0,g:1.0,b:0.5,a:0.0}),stroke:None,stroke_width:Some(0.0),opacity:Some(0.5)}],layers:vec![DrawLayer{id:f["layerId"].as_str().unwrap().into(),name:"".into(),visible:true,root:DrawNode::Group{transform:SemioTransform::identity(),children:vec![DrawNode::Path{style:Some("".into()),segments:vec![PathSegment::MoveTo{to:a},PathSegment::LineTo{to:b},PathSegment::CubicTo{c1:a,c2:b,to:a},PathSegment::QuadTo{c:b,to:a},PathSegment::ArcTo{rx:2.0,ry:3.0,x_rotation:-4.0,large_arc:true,sweep:false,to:b},PathSegment::Close]},DrawNode::Text{value:f["text"].as_str().unwrap().into(),at:b,style:Some("".into())},DrawNode::Image{at:a,width:0.0,height:-1.0,mime:f["mime"].as_str().unwrap().into(),bytes:vec![0,255,127]},DrawNode::Group{transform:SemioTransform::identity(),children:vec![]}]}},DrawLayer{id:"hidden".into(),name:"hidden".into(),visible:false,root:DrawNode::Text{value:"".into(),at:a,style:None}}]}}
fn project(s:&SemioDrawingSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioDrawingSnapshot,String>{SemioDrawingSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_drawing_all_nodes_segments_optional_colors_and_native_state(){let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let r=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(r,s);assert_eq!(<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(&s));assert_eq!(<SemioDrawingSnapshot as store::ArtifactDsl>::print_dsl(&r),<SemioDrawingSnapshot as store::ArtifactDsl>::print_dsl(&s));assert_eq!(restore(&project(&SemioDrawingSnapshot::default())).unwrap(),SemioDrawingSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_drawing_rejects_cycles_style_segment_color_shapes_and_budgets(){let original=project(&fixture());for change in 0..6{let mut db=original.clone();match change{0=>db.table_mut("semio_drawing_child").unwrap().rows[0].values[3]=SqliteValue::Integer(1),1=>db.table_mut("semio_drawing_path").unwrap().rows[0].values[1]=SqliteValue::Integer(999),2=>db.table_mut("semio_drawing_arc").unwrap().rows[0].values[4]=SqliteValue::Integer(2),3=>db.table_mut("semio_drawing_style").unwrap().rows[0].values[4]=SqliteValue::Null,4=>db.table_mut("semio_drawing_segment").unwrap().rows[0].values[2]=SqliteValue::Integer(99),_=>{db.table_mut("semio_drawing_line").unwrap().rows.clear();}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioDrawingSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_drawing_independent_path_style_query_and_text_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT text,name FROM semio_drawing_text JOIN semio_drawing_style ON style_id=semio_drawing_style.id').get().name!=='')throw Error('style reference');if(db.query('SELECT count(*) AS n FROM semio_drawing_segment').get().n!==6)throw Error('segments');db.query(\"UPDATE semio_drawing_text SET text='independently edited' WHERE style_id IS NOT NULL\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let DrawNode::Group{children,..}=&mut expected.layers[0].root{if let DrawNode::Text{value,..}=&mut children[1]{*value="independently edited".into();}}assert_eq!(r,expected);}

#[test]
fn sqlite_snapshot_semio_drawing_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioDrawingSnapshot,crate::standards::v1::subsets::drawing::schema::mutations::SemioDrawingMutation>("s.stdio.semio.drawing");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioDrawingSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"drawing".into()};let db=(provider.export)("s.stdio.semio.drawing",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.drawing",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_drawing_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let v32=f32::from_bits(bits32);let mut s=fixture();s.canvas.width=v;s.canvas.background.as_mut().unwrap().r=v32;let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((r.canvas.width).to_bits(),bits);assert_eq!(r.canvas.background.unwrap().r.to_bits(),bits32);assert_eq!(<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_drawing_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_drawing_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_drawing_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"drawing".into()};
    let provider=<SemioDrawingSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioDrawingSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioDrawingSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert_eq!(actual,expected);
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioDrawingSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_semio_drawing_native_text_preserves_ieee_words(){use store::ArtifactDsl;let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for word in f["float64Bits"].as_array().unwrap(){let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let mut value=fixture();value.canvas.width=f64::from_bits(bits);let actual=SemioDrawingSnapshot::parse_dsl(&value.print_dsl()).unwrap();assert_eq!(actual.canvas.width.to_bits(),bits);}for word in f["float32Bits"].as_array().unwrap(){let bits=u32::from_str_radix(word.as_str().unwrap(),16).unwrap();let mut value=fixture();value.canvas.background.as_mut().unwrap().r=f32::from_bits(bits);let actual=SemioDrawingSnapshot::parse_dsl(&value.print_dsl()).unwrap();assert_eq!(actual.canvas.background.unwrap().r.to_bits(),bits);}}
#[test]
fn sqlite_snapshot_semio_drawing_explicit_controlled_native_owner(){use store::{ArtifactPack,ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let expected=fixture();for payload in [store::os_io::IoPayload::Binary(expected.encode_pack()),store::os_io::IoPayload::Text(expected.print_dsl())]{let actual=SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual,expected);assert!(SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());assert!(SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());}let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let value=SemioDrawingSnapshot{schema:expected.schema,layers:vec![DrawLayer{id:"layer".into(),name:"".into(),visible:true,root:DrawNode::Group{transform:SemioTransform::identity(),children:(0..count).map(|_|DrawNode::Text{value:"".into(),at:SemioPoint2{x:-0.0,y:0.0},style:None}).collect()}}],..SemioDrawingSnapshot::default()};for payload in [store::os_io::IoPayload::Binary(value.encode_pack()),store::os_io::IoPayload::Text(value.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(SemioDrawingSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(interior);}let mut root=DrawNode::default();for _ in 0..f["nativeAdmission"]["maximumDepth"].as_u64().unwrap()+1{root=DrawNode::Group{transform:SemioTransform::identity(),children:vec![root]};}let deep=SemioDrawingSnapshot{layers:vec![DrawLayer{id:"deep".into(),root,..DrawLayer::default()}],..SemioDrawingSnapshot::default()};assert!(SemioDrawingSnapshot::decode_sqlite_snapshot_native(&store::os_io::IoPayload::Binary(deep.encode_pack()),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}

