fn sqlite_snapshot_semio_drawing_controlled_native_output(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let count=corpus["nativeOutputBytes"].as_u64().unwrap() as usize;let mut snapshot=fixture();if let DrawNode::Group{children,..}=&mut snapshot.layers[0].root{if let DrawNode::Image{bytes,..}=&mut children[2]{*bytes=vec![127;count]}else{panic!("fixture image")}}else{panic!("fixture group")};crate::standards::v1::subsets::base::schema::snapshot::native_output_tests::assert_output(&snapshot);}

#[test]
fn sqlite_snapshot_semio_drawing_late_reconstruction_cancellation_retires_owned_tree(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let limits=&corpus["reconstructionRetirement"];let depth=limits["depth"].as_u64().unwrap() as usize;let stack=limits["stackBytes"].as_u64().unwrap() as usize;let bytes=limits["schemaBytes"].as_u64().unwrap() as usize;let mut snapshot=fixture();snapshot.schema="x".repeat(bytes);let mut node=DrawNode::Text{value:String::new(),at:SemioPoint2{x:0.0,y:0.0},style:None};for _ in 0..depth{node=DrawNode::Group{transform:SemioTransform::identity(),children:vec![node]};}snapshot.layers[0].root=node;crate::standards::v1::subsets::base::schema::snapshot::native_output_tests::assert_reconstruction(snapshot,bytes,stack);}

fn component_database()->(SqliteDatabase,String){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧩️component.json")).unwrap();let mut database=project(&fixture());let sql=format!("{}\n{}",SemioDrawingSnapshot::SQLITE_SCHEMA,f["sql"].as_str().unwrap());let mut parent=SqliteDatabase::from_schema(f["sql"].as_str().unwrap()).unwrap().tables.remove(0);let mut values=vec![SqliteValue::Integer(1)];values.extend(f["identity"].as_array().unwrap().iter().map(|v|SqliteValue::Text(v.as_str().unwrap().into())));values.push(SqliteValue::Integer(1));parent.rows.push(SqliteRow{rowid:1,values});database.tables.push(parent);(database,sql)}
#[test]
fn sqlite_snapshot_semio_drawing_borrowed_relational_component(){use std::io::Write;use std::process::{Command,Stdio};let(database,sql)=component_database();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut oracle=Command::new("bun").args(["-e","import{Database}from'bun:sqlite';import Ajv from'ajv/dist/2020.js';const f=await Bun.file(process.argv[1]).json(),s=await Bun.file(process.argv[2]).json();if(!new Ajv({strict:true}).validate(s,f))throw Error('fixture');const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA foreign_key_check').all().length)throw Error('relations');const x=d.query('SELECT child_id,artifact_kind,standard,subset,document_id FROM layout_drawing_component JOIN semio_drawing_document ON drawing_id=semio_drawing_document.id').get();if(JSON.stringify(Object.values(x))!==JSON.stringify(f.identity))throw Error('literal identity');d.close();",concat!(env!("CARGO_MANIFEST_DIR"),"/../../🏅️standards/🔖️v1/🪆️subsets/🖊️drawing/🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧩️component.json"),concat!(env!("CARGO_MANIFEST_DIR"),"/../../🏅️standards/🔖️v1/🪆️subsets/🖊️drawing/🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🧬️schema/🧩️component.json")]).stdin(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();oracle.stdin.take().unwrap().write_all(&bytes).unwrap();let result=oracle.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let blob=database.table("semio_drawing_image").unwrap().rows[0].blob(6).unwrap();let pointer=blob.as_ptr();let restored=SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()),&sql).unwrap();assert_eq!(restored,fixture());assert_eq!(database.table("semio_drawing_image").unwrap().rows[0].blob(6).unwrap().as_ptr(),pointer);let rows=database.tables.iter().map(|t|t.rows.len()).sum::<usize>();assert!(SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()}),&sql).is_err());assert!(SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()),&sql).is_err());}
#[test]
fn sqlite_snapshot_semio_drawing_parent_cannot_weaken_component_schema(){let(mut database,sql)=component_database();let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧩️component.json")).unwrap();let from=f["weakenedColumn"].as_str().unwrap();let into=f["weakenedReplacement"].as_str().unwrap();database.table_mut("semio_drawing_document").unwrap().sql=database.table("semio_drawing_document").unwrap().sql.replace(from,into);assert!(SemioDrawingSnapshot::reconstruct_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()),&sql.replace(from,into)).is_err(),"parent declaration must not weaken the owned Drawing schema");}
